-- G-16: student IDs used to be generated by a 10-attempt random-retry loop checking
-- existsByStudentId, which left a narrow race window under concurrent creation (two
-- requests could each pass the uniqueness check before either commits). A DB-backed
-- sequence makes allocation atomic — every caller gets a distinct value directly from
-- Postgres, with no check-then-act gap. The public STU-<year>-<4 digits> format is
-- unchanged; see UserService.generateUniqueStudentId(). See docs/gap-analysis-report.md G-16.

CREATE SEQUENCE IF NOT EXISTS student_id_seq START WITH 1 INCREMENT BY 1;
